// @ts-check
// The UI's generated files (ADR-0035, decisions 7 and 8): the static plugin
// lists that the composition root imports as `#plugin-list`, and each
// plugin's barrel of its own messages.
//
// The list of the builds that ship names the shipped plugins, and the list of
// the validation builds also the fixture plugins, each in the order of their
// starts. An entry carries the plugin's name and description from the catalog
// and the definition that its `ui/index.ts` exports, or none for a plugin
// without UI, so the Plugins page names every plugin. A plugin imports its
// messages from its barrel, `ui/generated/messages.ts`, which re-exports only
// the keys of the plugin's catalog, so the type checks refuse a key of the
// core or of another plugin.

import { existsSync } from 'node:fs';
import { join, posix } from 'node:path';

import { prefixOf } from './manifests.mjs';

/**
 * @typedef {import('./generator.mjs').GeneratedFile} GeneratedFile
 */

/**
 * A plugin as the UI's lists name it.
 * @typedef {object} UiPlugin
 * @property {string} folder the plugin's folder, relative to the root, with forward slashes
 * @property {boolean} hasUi whether the plugin has `ui/index.ts`
 * @property {string} id
 * @property {boolean} validation whether only validation builds bundle it
 */

/** The folder of the generated plugin lists, relative to the root. */
export const UI_LIST_FOLDER = 'apps/desktop/src/lib/generated';
/** The compiled catalog that the barrels re-export, relative to the root. */
export const COMPILED_MESSAGES = 'apps/desktop/src/lib/paraglide/messages.js';

const HEADER = (/** @type {string} */ source) =>
  `// Generated by \`task gen\` from ${source} (ADR-0035, decisions 7 and 8). Do not edit or commit it.\n`;

/**
 * The plugins as the UI's lists name them, with whether each has UI.
 * @param {string} root
 * @param {{ folder: string, id: string, validation: boolean }[]} plugins in the order of their starts
 * @returns {UiPlugin[]}
 */
export function uiPlugins(root, plugins) {
  return plugins.map((plugin) => ({
    folder: plugin.folder,
    hasUi: existsSync(join(root, plugin.folder, 'ui', 'index.ts')),
    id: plugin.id,
    validation: plugin.validation,
  }));
}

/**
 * The name that a plugin's definition gets in a list: its ID in camel case
 * with `Plugin` after it, so that no ID clashes with a keyword or with `m`.
 * @param {string} id
 */
function definitionName(id) {
  const words = id.split('-');
  const capitalized = words.slice(1).map((word) => `${word.charAt(0).toUpperCase()}${word.slice(1)}`);
  return `${String(words[0])}${capitalized.join('')}Plugin`;
}

/**
 * A plugin list of the UI.
 * @param {UiPlugin[]} plugins the list's plugins, in the order of their starts
 * @param {string} description what the list holds, for its comment
 * @returns {string}
 */
export function uiPluginList(plugins, description) {
  const imports = plugins
    .filter((plugin) => plugin.hasUi)
    .map(
      (plugin) =>
        `import ${definitionName(plugin.id)} from '${posix.relative(UI_LIST_FOLDER, plugin.folder)}/ui/index.js';\n`,
    );
  const entries = plugins.map((plugin) => {
    const prefix = prefixOf(plugin.id);
    const definition = plugin.hasUi ? definitionName(plugin.id) : 'null';
    return [
      '  {\n',
      `    definition: ${definition},\n`,
      `    description: m.${prefix}_plugin_description,\n`,
      `    id: '${plugin.id}',\n`,
      `    name: m.${prefix}_plugin_name,\n`,
      '  },\n',
    ].join('');
  });
  return [
    HEADER("the plugins' manifests"),
    '//\n',
    `// ${description}\n`,
    '\n',
    "import { m } from '#lib/paraglide/messages.js';\n",
    "import type { PluginEntry } from '#lib/types/plugins.js';\n",
    ...(imports.length > 0 ? ['\n', ...imports] : []),
    '\n',
    '/** The plugins, in the order of their starts. */\n',
    'export const plugins: readonly PluginEntry[] = [\n',
    ...entries,
    '];\n',
  ].join('');
}

/**
 * The plugin lists of the UI: the one of the builds that ship, and the one
 * of the validation builds, which `#plugin-list` resolves to under the
 * `validation` condition (apps/desktop/package.json).
 * @param {UiPlugin[]} plugins every plugin, fixtures included, in the order of their starts
 * @returns {GeneratedFile[]}
 */
export function uiPluginLists(plugins) {
  return [
    {
      path: `${UI_LIST_FOLDER}/plugin-list.ts`,
      text: uiPluginList(
        plugins.filter((plugin) => !plugin.validation),
        'The plugins of the builds that ship. The composition root imports it as `#plugin-list`.',
      ),
    },
    {
      path: `${UI_LIST_FOLDER}/plugin-list.validation.ts`,
      text: uiPluginList(
        plugins,
        'The plugins of the validation builds, the fixture plugins included, which import it as `#plugin-list`.',
      ),
    },
  ];
}

/**
 * A plugin's barrel of its messages: `messages.ts`, which exports them as
 * `m`, and `message-list.ts`, which re-exports the keys of the plugin's
 * catalog from the compiled catalog.
 * @param {string} folder the plugin's folder, relative to the root
 * @param {string[]} keys the keys of the plugin's catalog in the base locale
 * @returns {GeneratedFile[]}
 */
export function messageBarrel(folder, keys) {
  const generated = `${folder}/ui/generated`;
  const compiled = posix.relative(generated, COMPILED_MESSAGES);
  const sorted = [...keys].sort();
  const list =
    sorted.length === 0
      ? ['export {};\n']
      : ['export {\n', ...sorted.map((key) => `  ${key},\n`), `} from '${compiled}';\n`];
  return [
    {
      path: `${generated}/messages.ts`,
      text: [
        HEADER("the plugin's catalog"),
        '//\n',
        "// The plugin's own messages as `m`, so that the type checks refuse a key\n",
        '// of the core or of another plugin.\n',
        '\n',
        "export * as m from './message-list.js';\n",
      ].join(''),
    },
    {
      path: `${generated}/message-list.ts`,
      text: [HEADER("the plugin's catalog"), '\n', ...list].join(''),
    },
  ];
}
